public:
    int containVirus(vector<vector<int>>& isInfected) {
        int m = isInfected.size(), n = isInfected[0].size();
        int totalWalls = 0;
        int dirs[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        while (true) {
            vector<vector<bool>> visited(m, vector<bool>(n, false));
            vector<vector<pair<int, int>>> regions;
            vector<set<pair<int, int>>> threats;
            vector<int> wallsNeeded;

            for (int r = 0; r < m; r++) {
                for (int c = 0; c < n; c++) {
                    if (isInfected[r][c] == 1 && !visited[r][c]) {
                        vector<pair<int, int>> region;
                        set<pair<int, int>> threat;
                        int walls = 0;
                        vector<pair<int, int>> stk = {{r, c}};
                        visited[r][c] = true;
                        while (!stk.empty()) {
                            auto [cr, cc] = stk.back();
                            stk.pop_back();
                            region.push_back({cr, cc});
                            for (auto& dir : dirs) {
                                int nr = cr + dir[0], nc = cc + dir[1];
                                if (nr >= 0 && nr < m && nc >= 0 && nc < n) {
                                    if (isInfected[nr][nc] == 1 && !visited[nr][nc]) {
                                        visited[nr][nc] = true;
                                        stk.push_back({nr, nc});
                                    } else if (isInfected[nr][nc] == 0) {
                                        threat.insert({nr, nc});
                                        walls++;
                                    }
                                }
                            }
                        }
                        regions.push_back(region);
                        threats.push_back(threat);
                        wallsNeeded.push_back(walls);
                    }
                }
            }

            if (regions.empty()) break;
            int idx = -1, maxThreat = 0;
            for (int i = 0; i < (int)threats.size(); i++) {
                if ((int)threats[i].size() > maxThreat) {
                    maxThreat = threats[i].size();
                    idx = i;
                }
            }
            if (idx == -1) break;

            totalWalls += wallsNeeded[idx];
            for (auto& [r, c] : regions[idx]) isInfected[r][c] = 2;
            for (int i = 0; i < (int)regions.size(); i++) {
                if (i != idx) {
                    for (auto& [r, c] : threats[i]) isInfected[r][c] = 1;
                }
            }
        }
        return totalWalls;
    }
